const items = $input.all();
const rows = Array.isArray(items[0]?.json) ? items[0].json : (items[0]?.json?.observations ?? items.map(i => i.json));
return rows.map(row => {
  const total = Number(row.total_fare ?? row.totalFare ?? 0);
  const observed = new Date(row.observed_at ?? row.collected_at ?? Date.now());
  const travel = new Date(row.travel_date);
  const advance_days = Math.round((travel - observed) / 86400000);
  if (!/^[A-Z]{3}-[A-Z]{3}$/.test(row.route ?? '')) throw new Error('Invalid route');
  if (!(total > 0) || advance_days < 1) throw new Error('Invalid fare observation');
  return { json: { route: row.route, observed_at: observed.toISOString(), travel_date: row.travel_date, carrier_code: row.carrier_code, total_fare: total, advance_days, source: row.source ?? 'configured_source' } };
});
